	sections = {
		{
			title = "Summary",
			text = [=[The Frostmane are a tribe of {link:trolls}trolls{/link} who live in the snows of {link:dun-morogh}Dun Morogh{/link}. They are fierce and secretive, and they dispute these mountains with the dwarves. No chronicle records when they first came here.]=],
		},
		{
			title = "Their Lands",
			text = [=[Their greatest stronghold is {link:frostmane-hold}Frostmane Hold{/link}, a cavern south-west of {link:brewnall-village}Brewnall Village{/link}. They also keep camps upon {link:shimmer-ridge}Shimmer Ridge{/link} and a cave in the south of {link:coldridge-valley}Coldridge Valley{/link}, where the young whelps of the tribe dwell. Their warriors are headhunters and snowstriders. Their seers and shadowcasters work a magic of their own, and they gather shimmerweed for their rituals.]=],
		},
		{
			title = "In the Present Day",
			text = [=[The Senate of {link:ironforge}Ironforge{/link} has its hands full with the troggs, and it would rather not think of the trolls at all. Two brothers of the Whitebeard family were sent to learn how great the threat truly is. {link:grelin-whitebeard}Grelin{/link} judged the trolls of {link:coldridge-valley}Coldridge{/link} to be few. {link:senir-whitebeard}Senir{/link} found {link:frostmane-hold}Frostmane Hold{/link} full of them. Between the two reports lies the question of how much the dwarves can afford to ignore. In Coldridge, a troll called {link:grik-nir-the-cold}Grik'nir the Cold{/link} has stolen more than a journal from the dwarves: he has shown them that the Frostmane are watching.]=],
		},
	},
})

Add({
	kind = "topic",
	id = "gnomeregan-exiles",
	title = "Gnomeregan Exiles",
	aliases = { "exiles of Gnomeregan" },
	category = "group",
	region = "dun-morogh",
	unlock = {
		{ type = "read" },
		{ type = "quest", id = 3361 },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Gnomeregan Exiles are the gnomes who survived the fall of their city. They are a people without a home. Most of them live in {link:ironforge}Ironforge{/link}, where King {link:magni-bronzebeard}Magni Bronzebeard{/link} gave them room in {link:tinker-town}Tinker Town{/link}, but they are scattered across {link:dun-morogh}Dun Morogh{/link} and beyond.]=],
		},
		{
			title = "After the Fall",
			text = [=[The troggs came up beneath {link:gnomeregan}Gnomeregan{/link}, and the gnomes drove them back with a weapon of their own making. It went horribly wrong. The city was poisoned, and many of its people were changed into sick and witless lepers who still wander before its gates. The rest fled into the snow with whatever they could carry. Some lost everything to the trolls on the way. Others left behind the records of their families, their inventions and their craft.]=],
		},
		{
			title = "In the Present Day",
			text = [=[The exiles have not given up. In {link:kharanos}Kharanos{/link}, {link:razzle-sprysprocket}Razzle Sprysprocket{/link} and Ozzie Togglevolt are building a machine they hope will restore the poisoned gnomes. In {link:ironforge}Ironforge{/link}, the tinkers of {link:gnomeregan}Gnomeregan{/link} send brave strangers back into the city to rescue its lost knowledge. High Tinker {link:gelbin-mekkatorque}Gelbin Mekkatorque{/link} swears that his people will take their home back from the traitor who holds it.]=],
		},
	},
})

